package main

import (
	"fmt"
	"unicode"
)

// For a given string, flip lowercase characters to uppercase and uppercase to lowercase.
// >>> FlipCase('Hello')
// 'hELLO'
func FlipCase(str string) string {
	// Convert string to a slice of runes to handle multi-byte Unicode characters correctly
	runes := []rune(str)

	for i, r := range runes {
		if unicode.IsUpper(r) {
			runes[i] = unicode.ToLower(r)
		} else if unicode.IsLower(r) {
			runes[i] = unicode.ToUpper(r)
		}
		// If it's not a letter (e.g., digit, space, punctuation), it remains unchanged
	}

	return string(runes)
}

func main() {
	fmt.Println(FlipCase("Hello")) // Output: hELLO
	fmt.Println(FlipCase("GoLang 1.21")) // Output: gOlANG 1.21
}
```

### Explanation:
1.  **`[]rune(str)`**: Strings in Go are UTF-8 encoded byte slices. Converting the string to a `[]rune` allows us to iterate through individual Unicode characters (code points) rather than individual bytes. This ensures the function works correctly even if the string contains special characters (like accented letters).
2.  **`unicode.IsUpper(r)` / `unicode.IsLower(r)`**: These standard library functions accurately detect the case of a character based on Unicode standards.
3.  **`unicode.ToUpper(r)` / `unicode.ToLower(r)`**: These perform the actual transformation.
4.  **Complexity**: 
    *   **Time Complexity**: $O(n)$, where $n$ is the number of characters in the string, as we traverse the string once.
    *   **Space Complexity**: $O(n)$ to store the resulting slice of runes.

