```cpp
#include <stdio.h>
#include <string>
#include <openssl/md5.h>
#include <iomanip>
#include <sstream>

using namespace std;

string string_to_md5(string text) {
    // If 'text' is an empty string, return "None" (or handle as per specific requirement)
    // Based on the prompt's logic for empty string:
    if (text.empty()) {
        return "None"; 
    }

    unsigned char digest[MD5_DIGEST_LENGTH];

    // Perform the MD5 hash
    // MD5() takes: (data_pointer, data_length, output_buffer)
    MD5((unsigned char*)text.c_str(), text.length(), digest);

    // Convert the byte array to a hexadecimal string
    stringstream ss;
    for(int i = 0; i < MD5_DIGEST_LENGTH; i++) {
        // setw(2) and setfill('0') ensure we get "0a" instead of just "a"
        ss << hex << setw(2) << setfill('0') << (int)digest[i];
    }

    return ss.str();
}

// To test the implementation
int main() {
    string input = "Hello world";
    string result = string_to_md5(input);
    printf("Input: %s\nMD5: %s\n", input.c_str(), result.c_str());
    // Expected: 3e25960a79dbc69b674cd4ec67a72c62
    return 0;
}
```

